<template>
  <BioNexusDialog ref="dialog" size="wide" :prevent-close="saving || dirty" kicker="Nuevo registro" title="Registrar pago" :subtitle="laboratory ? `${laboratory.name} · ${laboratory.rif}` : ''" @before-close="requestClose" @close="reset">
    <section class="payment-dialog-body"><BioNexusFormErrors :errors="errorMessage" />
      <BioNexusSectionPanel title="Información del pago" icon="payments" description="Registra la fecha, monto, moneda, método y referencia del pago." variant="accent"><div class="payment-fields">
        <BioNexusFormField label="Fecha de pago" field-id="payment-paid-at" required><input id="payment-paid-at" ref="firstInput" v-model="draft.paidAt" class="bio-nexus-field" type="date" :disabled="saving" @change="syncDirty" /></BioNexusFormField>
        <BioNexusFormField label="Monto" field-id="payment-amount" required :error="fieldErrors.amount"><BioNexusNumericInput id="payment-amount" v-model="draft.amount" :decimals="2" :min="0.01" :disabled="saving" @input="syncDirty" /></BioNexusFormField>
        <BioNexusFormField label="Moneda" field-id="payment-currency" required :error="fieldErrors.currency" :help="`${draft.currency.length} de 3 caracteres`"><input id="payment-currency" v-model.trim="draft.currency" class="bio-nexus-field" maxlength="3" placeholder="USD" :disabled="saving" @input="normalizeCurrency" /></BioNexusFormField>
        <BioNexusFormField label="Método de pago" field-id="payment-method" required :error="fieldErrors.method" :help="`${draft.method.length} de 100 caracteres`"><input id="payment-method" v-model.trim="draft.method" class="bio-nexus-field" maxlength="100" :disabled="saving" @input="syncDirty" /></BioNexusFormField>
        <BioNexusFormField class="wide" label="Referencia (opcional)" field-id="payment-reference" :help="`${draft.reference.length} de 200 caracteres`"><input id="payment-reference" v-model.trim="draft.reference" class="bio-nexus-field" maxlength="200" :disabled="saving" @input="syncDirty" /></BioNexusFormField>
      </div></BioNexusSectionPanel>
      <BioNexusSectionPanel title="Período del servicio" icon="date_range" description="Define la vigencia cubierta por este pago." variant="accent" compact><div class="payment-fields"><BioNexusFormField label="Inicio" field-id="payment-period-start" required><input id="payment-period-start" v-model="draft.periodStart" class="bio-nexus-field" type="date" :disabled="saving" @change="syncDirty" /></BioNexusFormField><BioNexusFormField label="Fin" field-id="payment-period-end" required :error="fieldErrors.period"><input id="payment-period-end" v-model="draft.periodEnd" class="bio-nexus-field" type="date" :disabled="saving" @change="syncDirty" /></BioNexusFormField></div></BioNexusSectionPanel>
      <BioNexusSectionPanel title="Comprobante" icon="attach_file" description="Adjunta opcionalmente PNG, JPEG, WebP o PDF, con un máximo de 10 MiB." variant="soft" compact><BioNexusFormField label="Archivo opcional" field-id="payment-proof" :error="fieldErrors.proof"><input id="payment-proof" ref="fileInput" class="bio-nexus-field" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" :disabled="saving" @change="selectProof" /><small v-if="proof">{{proof.name}} · {{formatFileSize(proof.size)}}</small></BioNexusFormField></BioNexusSectionPanel>
    </section>
    <template #footer><BioNexusActionButton variant="secondary" icon="cancel" :disabled="saving" @click="requestClose">Cancelar</BioNexusActionButton><BioNexusActionButton variant="primary" icon="payments" :loading="saving" :disabled="saving || !dirty" @click="submit">Registrar pago</BioNexusActionButton></template>
  </BioNexusDialog><BioNexusConfirmDialog ref="discardDialog" />
</template>
<script setup>
import{computed,nextTick,reactive,ref}from'vue';import BioNexusDialog from'@/components/ui/BioNexusDialog.vue';import BioNexusConfirmDialog from'@/components/ui/BioNexusConfirmDialog.vue';import BioNexusActionButton from'@/components/ui/BioNexusActionButton.vue';import BioNexusFormErrors from'@/components/ui/BioNexusFormErrors.vue';import BioNexusFormField from'@/components/ui/BioNexusFormField.vue';import BioNexusNumericInput from'@/components/ui/BioNexusNumericInput.vue';import BioNexusSectionPanel from'@/components/ui/BioNexusSectionPanel.vue'
const MAX_PROOF_SIZE=10*1024*1024,ALLOWED_PROOF_TYPES=new Set(['image/png','image/jpeg','image/webp','application/pdf']),props=defineProps({saving:Boolean}),emit=defineEmits(['submit']),dialog=ref(null),discardDialog=ref(null),firstInput=ref(null),fileInput=ref(null),laboratory=ref(null),proof=ref(null),errorMessage=ref(''),original=ref(''),dirty=ref(false),fieldErrors=reactive({amount:'',currency:'',method:'',period:'',proof:''}),draft=reactive(blank());let idempotencyKey=''
function todayLocal(){const date=new Date();return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}function blank(){const today=todayLocal();return{paidAt:today,amount:'',currency:'USD',method:'',reference:'',periodStart:today,periodEnd:today}}function toUtcDate(value){return new Date(`${value}T00:00:00.000Z`).toISOString()}function createIdempotencyKey(){if(!globalThis.crypto?.getRandomValues)throw new Error('El navegador no puede generar una clave segura para el registro del pago.');const bytes=globalThis.crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;return[...bytes].map((byte,index)=>`${[4,6,8,10].includes(index)?'-':''}${byte.toString(16).padStart(2,'0')}`).join('')}
const signature=computed(()=>JSON.stringify({...draft,proof:proof.value?{name:proof.value.name,size:proof.value.size,type:proof.value.type,lastModified:proof.value.lastModified}:null}));function clearErrors(){Object.keys(fieldErrors).forEach(key=>fieldErrors[key]='');errorMessage.value=''}function syncDirty(){clearErrors();dirty.value=signature.value!==original.value}async function open(row){laboratory.value=row;Object.assign(draft,blank());proof.value=null;idempotencyKey='';clearErrors();await dialog.value?.open();await nextTick();original.value=signature.value;dirty.value=false;firstInput.value?.focus()}function normalizeCurrency(){draft.currency=draft.currency.toUpperCase().replace(/[^A-Z]/g,'').slice(0,3);syncDirty()}
function selectProof(event){fieldErrors.proof='';const selected=event.target.files?.[0]||null;if(!selected){proof.value=null;syncDirty();return}if(!ALLOWED_PROOF_TYPES.has(selected.type)){event.target.value='';proof.value=null;fieldErrors.proof='El comprobante debe ser PNG, JPEG, WebP o PDF.';return}if(selected.size>MAX_PROOF_SIZE){event.target.value='';proof.value=null;fieldErrors.proof='El comprobante no puede superar 10 MiB.';return}proof.value=selected;syncDirty()}function validate(){clearErrors();if(!(Number(draft.amount)>0))fieldErrors.amount='El monto debe ser mayor que cero.';if(!/^[A-Z]{3}$/.test(draft.currency))fieldErrors.currency='La moneda debe tener exactamente tres letras mayúsculas.';if(!draft.method.trim())fieldErrors.method='El método de pago es obligatorio.';if(draft.periodEnd<draft.periodStart)fieldErrors.period='El fin del período no puede ser anterior a su inicio.';return!Object.values(fieldErrors).some(Boolean)}function submit(){if(!validate())return;try{if(!idempotencyKey)idempotencyKey=createIdempotencyKey()}catch(error){errorMessage.value=error.message;return}emit('submit',{values:{paidAt:toUtcDate(draft.paidAt),amount:Number(draft.amount),currency:draft.currency,method:draft.method.trim(),...(draft.reference.trim()?{reference:draft.reference.trim()}:{}),periodStart:toUtcDate(draft.periodStart),periodEnd:toUtcDate(draft.periodEnd),idempotencyKey},proof:proof.value})}
async function requestClose(){if(props.saving)return;if(dirty.value){const ok=await discardDialog.value?.ask({kicker:'Confirmación',title:'Descartar cambios',message:'Hay cambios sin guardar. ¿Deseas salir y descartarlos?',icon:'warning',variant:'danger',confirmIcon:'delete',confirmText:'Sí, salir y descartar cambios',cancelText:'Cancelar'});if(!ok)return}dialog.value?.close()}function markSavedAndClose(){original.value=signature.value;dirty.value=false;dialog.value?.close()}function reset(){Object.assign(draft,blank());proof.value=null;idempotencyKey='';original.value='';dirty.value=false;clearErrors();if(fileInput.value)fileInput.value.value=''}function formatFileSize(size){return`${(size/(1024*1024)).toFixed(2)} MiB`}defineExpose({open,markSavedAndClose,setError:value=>errorMessage.value=String(value||''),clearError:()=>errorMessage.value=''})
</script>
<style scoped>.payment-dialog-body{display:grid;gap:var(--bio-nexus-space-4);font-family:var(--bio-nexus-font-family)}.payment-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--bio-nexus-space-3)}.wide{grid-column:1/-1}@media(max-width:700px){.payment-fields{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
